import"./chunk-VC46IEJQ.js";var e=(a,s,o,i,d,h,r,n,t)=>({name:{en:a[0],zh:a[1]},desc:{en:s[0],zh:s[1]},tour:{en:o[0],zh:o[1]},...t?{spoiler:{en:t[0],zh:t[1]}}:{},source:{confidence:i,refs:d,book:{en:h[0],zh:h[1]},unknown:{en:r[0],zh:r[1]},interpretation:{en:n[0],zh:n[1]}}}),l={id:"white-harbor",intro:{en:"The North's only city stands where the White Knife meets the sea: a walled town of white stone, a busy harbour, and House Manderly's New Castle on the hill. The old Wolf's Den still squats by the water.",zh:"\u5317\u5883\u552F\u4E00\u7684\u57CE\u5E02\u5750\u843D\u5728\u767D\u5203\u6CB3\u5165\u6D77\u53E3\uFF1A\u767D\u77F3\u780C\u6210\u7684\u57CE\u5899\u4E0E\u8857\u5DF7\u3001\u7E41\u5FD9\u7684\u6E2F\u53E3\uFF0C\u8FD8\u6709\u5C71\u4E18\u4E0A\u66FC\u5FB7\u52D2\u5BB6\u65CF\u7684\u65B0\u5821\u3002\u53E4\u8001\u7684\u72FC\u7A74\u4F9D\u65E7\u8E72\u8E1E\u5728\u6C34\u8FB9\u3002"},notes:{en:"From the novels (chiefly the fifth) and TWOIAF: a walled city of white stone at the mouth of the White Knife, the New Castle as the Manderly seat, the ancient Wolf's Den, the Castle Stair between them, the Seal Gate and Fishfoot Yard, the Sept of the Snows, the Merman's Court and a busy harbour. Invented here: the street plan, building shapes, ship traffic and every position.",zh:"\u51FA\u81EA\u5C0F\u8BF4\uFF08\u4E3B\u8981\u662F\u7B2C\u4E94\u5377\uFF09\u4E0E\u300A\u51B0\u4E0E\u706B\u4E4B\u6B4C\uFF1A\u4E16\u754C\u300B\uFF1A\u767D\u5203\u6CB3\u53E3\u4E00\u5EA7\u767D\u77F3\u57CE\u5899\u73AF\u7ED5\u7684\u57CE\u5E02\u3001\u66FC\u5FB7\u52D2\u5BB6\u65CF\u7684\u5C45\u57CE\u65B0\u5821\u3001\u53E4\u8001\u7684\u72FC\u7A74\u3001\u8FDE\u63A5\u4E24\u8005\u7684\u57CE\u5821\u9636\u68AF\u3001\u6D77\u8C79\u95E8\u4E0E\u9C7C\u811A\u5E7F\u573A\u3001\u96EA\u4E4B\u5723\u5802\u3001\u4EBA\u9C7C\u5BAB\uFF0C\u4EE5\u53CA\u7E41\u5FD9\u7684\u6E2F\u53E3\u3002\u672C\u573A\u666F\u81EA\u884C\u8BBE\u8BA1\uFF1A\u8857\u9053\u5E03\u5C40\u3001\u5EFA\u7B51\u9020\u578B\u3001\u8239\u53EA\u5F80\u6765\u53CA\u6240\u6709\u4F4D\u7F6E\u3002"},tour:["harbour-quays","city-walls","seal-gate","fishfoot-yard","sept-of-the-snows","wolfs-den","castle-stair","new-castle","mermans-court","white-knife"],sources:[{ref:"adwd",checked:"memory",note:{en:"Davos's chapters show the harbour, the city, the Wolf's Den, the New Castle and the Manderly court; recalled, not re-read.",zh:"\u6234\u4F5B\u65AF\u7684\u7AE0\u8282\u5199\u5230\u6E2F\u53E3\u3001\u57CE\u533A\u3001\u72FC\u7A74\u3001\u65B0\u5821\u4E0E\u66FC\u5FB7\u52D2\u5BB6\u7684\u5BAB\u5EF7\uFF1B\u51ED\u8BB0\u5FC6\uFF0C\u672A\u91CD\u8BFB\u3002"}},{ref:"twoiaf",checked:"memory",note:{en:"The city's history: the Starks' Wolf's Den and the Manderlys' arrival from the Reach; recalled.",zh:"\u57CE\u5E02\u6CBF\u9769\uFF1A\u53F2\u5854\u514B\u5BB6\u65CF\u6240\u5EFA\u7684\u72FC\u7A74\uFF0C\u4EE5\u53CA\u66FC\u5FB7\u52D2\u5BB6\u65CF\u81EA\u6CB3\u6E7E\u5730\u5317\u8FC1\uFF1B\u51ED\u8BB0\u5FC6\u3002"}},{ref:"awoiaf",checked:"search-snippet",note:{en:"Search summaries of the wiki confirm the Castle Stair (a broad stepped street of white stone from the Wolf's Den to the New Castle, lit by marble mermaids), Fishfoot Yard (a cobbled square with a fountain just inside the Seal Gate), the fish market by the Seal Gate and the Sept of the Snows. Pages not fetched.",zh:"\u7EF4\u57FA\u641C\u7D22\u6458\u8981\u5370\u8BC1\u4E86\u57CE\u5821\u9636\u68AF\uFF08\u81EA\u72FC\u7A74\u901A\u5F80\u65B0\u5821\u7684\u767D\u77F3\u9636\u68AF\u8857\uFF0C\u4E24\u65C1\u5927\u7406\u77F3\u4EBA\u9C7C\u50CF\u6258\u706F\u7167\u8DEF\uFF09\u3001\u9C7C\u811A\u5E7F\u573A\uFF08\u6D77\u8C79\u95E8\u5185\u8BBE\u55B7\u6CC9\u7684\u9E45\u5375\u77F3\u5E7F\u573A\uFF09\u3001\u6D77\u8C79\u95E8\u5916\u7684\u9C7C\u5E02\u4EE5\u53CA\u96EA\u4E4B\u5723\u5802\u3002\u9875\u9762\u672A\u6293\u53D6\u3002"}}],landmarks:{"harbour-quays":e(["Harbour & Quays","\u6E2F\u53E3\u4E0E\u7801\u5934"],["A deep, sheltered harbour of piers and stone quays, crowded with merchant cogs and fishing boats.","\u6C34\u6DF1\u800C\u907F\u98CE\u7684\u6E2F\u6E7E\uFF0C\u6808\u6865\u4E0E\u77F3\u780C\u7801\u5934\u4E0A\u6324\u6EE1\u4E86\u5546\u8239\u548C\u6E14\u8239\u3002"],["Cogs and fishing boats crowd the quays of the North's only city.","\u5317\u5883\u552F\u4E00\u57CE\u5E02\u7684\u7801\u5934\u4E0A\uFF0C\u5546\u8239\u4E0E\u6E14\u8239\u6328\u6328\u6324\u6324\u3002"],"high",["adwd","twoiaf"],["A large, busy harbour, divided into outer and inner basins, trading with the south and across the narrow sea.","\u4E00\u5EA7\u7E41\u5FD9\u7684\u5927\u6E2F\uFF0C\u5206\u4E3A\u5916\u6E2F\u4E0E\u5185\u6E2F\uFF0C\u4E0E\u5357\u65B9\u53CA\u72ED\u6D77\u5BF9\u5CB8\u901A\u5546\u3002"],["The exact shape of the basins and the number of piers.","\u6E2F\u6C60\u7684\u786E\u5207\u5F62\u72B6\u4E0E\u6808\u6865\u6570\u91CF\u3002"],["Six piers, a curved breakwater and a lantern tower are invented.","\u516D\u5EA7\u6808\u6865\u3001\u5F27\u5F62\u9632\u6CE2\u5824\u4E0E\u706F\u5854\u5747\u4E3A\u81EA\u62DF\u3002"]),"city-walls":e(["City Walls","\u57CE\u5899"],["A ring of pale stone walls and towers on the landward side, pierced by gates.","\u9646\u4FA7\u4E00\u5708\u767D\u77F3\u57CE\u5899\u4E0E\u5854\u697C\uFF0C\u5F00\u6709\u6570\u5EA7\u57CE\u95E8\u3002"],["White Harbor is a walled city; its towers watch the landward approaches.","\u767D\u6E2F\u662F\u4E00\u5EA7\u6709\u57CE\u5899\u7684\u57CE\u5E02\uFF0C\u5854\u697C\u5B88\u671B\u7740\u9646\u8DEF\u6765\u5411\u3002"],"medium",["adwd","twoiaf"],["The city is walled, and much of it is built of white stone.","\u57CE\u5E02\u7B51\u6709\u57CE\u5899\uFF0C\u57CE\u4E2D\u5EFA\u7B51\u591A\u4EE5\u767D\u77F3\u780C\u6210\u3002"],["Wall height, number of gates and layout.","\u57CE\u5899\u9AD8\u5EA6\u3001\u57CE\u95E8\u6570\u91CF\u4E0E\u5E03\u5C40\u3002"],["Seven towers, three gates and a regular ring are invented.","\u4E03\u5EA7\u5854\u697C\u3001\u4E09\u5EA7\u57CE\u95E8\u4E0E\u89C4\u6574\u7684\u73AF\u5F62\u5747\u4E3A\u81EA\u62DF\u3002"]),"seal-gate":e(["Seal Gate","\u6D77\u8C79\u95E8"],["The harbour-side gate, with a fish market between it and the water.","\u4E34\u6E2F\u7684\u57CE\u95E8\uFF0C\u57CE\u95E8\u4E0E\u6C34\u8FB9\u4E4B\u95F4\u662F\u4E00\u7247\u9C7C\u5E02\u3002"],["Between the harbour and the Seal Gate, the fish market never sleeps.","\u6E2F\u53E3\u4E0E\u6D77\u8C79\u95E8\u4E4B\u95F4\uFF0C\u9C7C\u5E02\u4ECE\u65E9\u5230\u665A\u4E0D\u66FE\u51B7\u6E05\u3002"],"medium",["adwd","awoiaf"],["A Seal Gate leads from the harbour into the city, with a fish market outside it.","\u6D77\u8C79\u95E8\u7531\u6E2F\u53E3\u901A\u5165\u57CE\u5185\uFF0C\u95E8\u5916\u6709\u9C7C\u5E02\u3002"],["Its form and exact position in the wall.","\u5F62\u5236\u53CA\u5728\u57CE\u5899\u4E0A\u7684\u786E\u5207\u4F4D\u7F6E\u3002"],["Placed in the south wall facing the quays.","\u7F6E\u4E8E\u5357\u5899\uFF0C\u6B63\u5BF9\u7801\u5934\u3002"]),"fishfoot-yard":e(["Fishfoot Yard","\u9C7C\u811A\u5E7F\u573A"],["A cobbled square just inside the Seal Gate, with a fountain at its centre.","\u6D77\u8C79\u95E8\u5185\u7684\u9E45\u5375\u77F3\u5E7F\u573A\uFF0C\u4E2D\u592E\u6709\u4E00\u5EA7\u55B7\u6CC9\u3002"],["Fishfoot Yard: cobbles, a fountain, and the city's gossip.","\u9C7C\u811A\u5E7F\u573A\uFF1A\u9E45\u5375\u77F3\u3001\u55B7\u6CC9\uFF0C\u8FD8\u6709\u6EE1\u57CE\u7684\u95F2\u8BDD\u3002"],"medium",["adwd","awoiaf"],["A cobbled square with a fountain just inside the Seal Gate; the Old Mint stands on it.","\u6D77\u8C79\u95E8\u5185\u4E00\u5EA7\u8BBE\u6709\u55B7\u6CC9\u7684\u9E45\u5375\u77F3\u5E7F\u573A\uFF0C\u65E7\u94F8\u5E01\u5382\u5C31\u5728\u5E7F\u573A\u8FB9\u4E0A\u3002"],["How the square is laid out and used.","\u5E7F\u573A\u7684\u5E03\u5C40\u4E0E\u7528\u9014\u3002"],["Fourteen awninged market stalls are invented.","\u5341\u56DB\u4E2A\u5E26\u906E\u7BF7\u7684\u644A\u4F4D\u4E3A\u81EA\u62DF\u3002"]),"sept-of-the-snows":e(["Sept of the Snows","\u96EA\u4E4B\u5723\u5802"],["A large domed sept, the city's chief house of worship; in White Harbor, unlike most of the North, the Seven are the main faith.","\u4E00\u5EA7\u5B8F\u5927\u7684\u5706\u9876\u5723\u5802\uFF0C\u662F\u57CE\u4E2D\u9996\u8981\u7684\u793C\u62DC\u573A\u6240\uFF1B\u4E0E\u5317\u5883\u5927\u90E8\u5206\u5730\u65B9\u4E0D\u540C\uFF0C\u767D\u6E2F\u4E3B\u8981\u4FE1\u5949\u4E03\u795E\u3002"],["A great dome rises above the roofs: the Seven rule here, not the old gods.","\u4E00\u5EA7\u5DE8\u5927\u7684\u5706\u9876\u9AD8\u51FA\u5C4B\u810A\uFF1A\u5728\u8FD9\u91CC\uFF0C\u4E03\u795E\u6BD4\u65E7\u795E\u66F4\u53D7\u5C0A\u5949\u3002"],"medium",["adwd","awoiaf"],["A large domed sept stands in the city; the Manderlys and most townsfolk keep the Faith of the Seven.","\u57CE\u4E2D\u6709\u4E00\u5EA7\u5B8F\u5927\u7684\u5706\u9876\u5723\u5802\uFF1B\u66FC\u5FB7\u52D2\u5BB6\u65CF\u4E0E\u5927\u591A\u6570\u5E02\u6C11\u5949\u884C\u4E03\u795E\u4FE1\u4EF0\u3002"],["Its exact form and position.","\u786E\u5207\u5F62\u5236\u4E0E\u4F4D\u7F6E\u3002"],["A cruciform plan, the dome and seven rooftop statues are invented.","\u5341\u5B57\u5F62\u5E73\u9762\u3001\u5706\u9876\u53CA\u9876\u4E0A\u7684\u4E03\u5C0A\u96D5\u50CF\u5747\u4E3A\u81EA\u62DF\u3002"]),"wolfs-den":e(["Wolf's Den","\u72FC\u7A74"],["An ancient Stark fortress by the water, older than the city, now used chiefly as a prison.","\u6C34\u8FB9\u4E00\u5EA7\u53E4\u8001\u7684\u53F2\u5854\u514B\u8981\u585E\uFF0C\u6BD4\u57CE\u5E02\u8FD8\u8981\u53E4\u8001\uFF0C\u5982\u4ECA\u4E3B\u8981\u7528\u4F5C\u76D1\u7262\u3002"],["The Wolf's Den is older than the city around it.","\u72FC\u7A74\u6BD4\u73AF\u7ED5\u5B83\u7684\u57CE\u5E02\u8FD8\u8981\u53E4\u8001\u3002"],"high",["adwd","twoiaf","awoiaf"],["A castle built by the Starks to guard the river mouth; later given to the Manderlys and now serving as a prison.","\u53F2\u5854\u514B\u5BB6\u65CF\u4E3A\u627C\u5B88\u6CB3\u53E3\u800C\u5EFA\u7684\u57CE\u5821\uFF0C\u540E\u6765\u4EA4\u7ED9\u66FC\u5FB7\u52D2\u5BB6\u65CF\uFF0C\u5982\u4ECA\u7528\u4F5C\u76D1\u7262\u3002"],["How much still stands and what it looks like.","\u5982\u4ECA\u5B58\u7559\u591A\u5C11\u3001\u5916\u89C2\u5982\u4F55\u3002"],["A broken keep, two drum towers and rubble are invented.","\u6B8B\u7834\u7684\u4E3B\u5821\u3001\u4E24\u5EA7\u5706\u5854\u4E0E\u788E\u77F3\u5747\u4E3A\u81EA\u62DF\u3002"],["In the fifth book an important visitor is held here.","\u7B2C\u4E94\u5377\u4E2D\uFF0C\u4E00\u4F4D\u91CD\u8981\u6765\u5BA2\u88AB\u5173\u62BC\u4E8E\u6B64\u3002"]),"castle-stair":e(["Castle Stair","\u57CE\u5821\u9636\u68AF"],["A broad stepped street of white stone climbing from the Wolf's Den to the New Castle, lit by marble mermaids holding bowls of burning oil.","\u4E00\u6761\u5BBD\u9614\u7684\u767D\u77F3\u9636\u68AF\u8857\uFF0C\u4ECE\u72FC\u7A74\u62FE\u7EA7\u800C\u4E0A\u76F4\u8FBE\u65B0\u5821\uFF0C\u4E24\u65C1\u7684\u5927\u7406\u77F3\u4EBA\u9C7C\u6000\u62B1\u71C3\u6CB9\u706F\u76C6\uFF0C\u7167\u4EAE\u9053\u8DEF\u3002"],["Marble mermaids light the long stair between the two castles.","\u5927\u7406\u77F3\u4EBA\u9C7C\u6258\u7740\u706F\u706B\uFF0C\u7167\u4EAE\u4E24\u5EA7\u57CE\u5821\u4E4B\u95F4\u7684\u957F\u9636\u3002"],"medium",["adwd","awoiaf"],["A broad stair-street links the Wolf's Den and the New Castle, lined with lamp-bearing marble mermaids.","\u4E00\u6761\u5BBD\u9614\u7684\u9636\u68AF\u8857\u8FDE\u63A5\u72FC\u7A74\u4E0E\u65B0\u5821\uFF0C\u4E24\u4FA7\u7ACB\u7740\u6258\u706F\u7684\u5927\u7406\u77F3\u4EBA\u9C7C\u50CF\u3002"],["Its length and exact course.","\u957F\u5EA6\u4E0E\u786E\u5207\u8D70\u5411\u3002"],["A straight flight of sixteen steps is invented.","\u4E00\u6BB5\u7B14\u76F4\u7684\u5341\u516D\u7EA7\u53F0\u9636\u4E3A\u81EA\u62DF\u3002"],["A secret passage beneath the stair links the two castles.","\u9636\u68AF\u4E4B\u4E0B\u6709\u4E00\u6761\u5BC6\u9053\u8FDE\u63A5\u4E24\u5EA7\u57CE\u5821\u3002"]),"new-castle":e(["New Castle","\u65B0\u5821"],["The seat of House Manderly, on the hill above the harbour.","\u66FC\u5FB7\u52D2\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u5750\u843D\u5728\u4FEF\u77B0\u6E2F\u53E3\u7684\u5C71\u4E18\u4E0A\u3002"],["The Manderlys rule from the New Castle on its hill.","\u66FC\u5FB7\u52D2\u5BB6\u65CF\u5728\u5C71\u4E18\u4E0A\u7684\u65B0\u5821\u4E2D\u6CBB\u7406\u5168\u57CE\u3002"],"high",["adwd","twoiaf"],["The New Castle on its hill is the Manderly seat.","\u5C71\u4E18\u4E0A\u7684\u65B0\u5821\u662F\u66FC\u5FB7\u52D2\u5BB6\u65CF\u7684\u5C45\u57CE\u3002"],["Its layout and size.","\u5E03\u5C40\u4E0E\u89C4\u6A21\u3002"],["A square curtain wall, four towers and a keep are invented.","\u65B9\u5F62\u57CE\u5899\u3001\u56DB\u5EA7\u5854\u697C\u4E0E\u4E3B\u5821\u5747\u4E3A\u81EA\u62DF\u3002"]),"mermans-court":e(["Merman's Court","\u4EBA\u9C7C\u5BAB"],["The New Castle's great hall, where the Lord of White Harbor sits in state; marble mermen guard its doors.","\u65B0\u5821\u7684\u5927\u5385\uFF0C\u767D\u6E2F\u9886\u4E3B\u5728\u6B64\u4E34\u671D\u542C\u653F\uFF1B\u95E8\u5916\u6709\u5927\u7406\u77F3\u4EBA\u9C7C\u50CF\u5B88\u536B\u3002"],["In the Merman's Court the Manderlys hold court and feast.","\u66FC\u5FB7\u52D2\u5BB6\u65CF\u5728\u4EBA\u9C7C\u5BAB\u4E2D\u8BAE\u4E8B\u3001\u8BBE\u5BB4\u3002"],"medium",["adwd","awoiaf"],["The great hall of the New Castle, where the lord holds court; its decoration follows the house's sea theme.","\u65B0\u5821\u7684\u5927\u5385\uFF0C\u9886\u4E3B\u5728\u6B64\u5904\u7406\u653F\u52A1\uFF1B\u88C5\u9970\u6CBF\u7528\u5BB6\u65CF\u7684\u6D77\u6D0B\u4E3B\u9898\u3002"],["Its size and interior arrangement.","\u89C4\u6A21\u4E0E\u5185\u90E8\u5E03\u7F6E\u3002"],["A gabled timber hall beside the keep; no interior is shown.","\u4E3B\u5821\u65C1\u4E00\u5EA7\u5E26\u5C71\u5899\u7684\u6728\u6784\u5385\u5802\uFF1B\u672A\u5448\u73B0\u5185\u90E8\u3002"],["Several pivotal scenes of the fifth book take place here.","\u7B2C\u4E94\u5377\u4E2D\u597D\u51E0\u573A\u5173\u952E\u620F\u90FD\u53D1\u751F\u5728\u8FD9\u91CC\u3002"]),"white-knife":e(["White Knife","\u767D\u5203\u6CB3"],["The river whose mouth forms White Harbor's anchorage, flowing down from the heart of the North.","\u81EA\u5317\u5883\u8179\u5730\u5954\u6D41\u800C\u4E0B\u7684\u6CB3\u6D41\uFF0C\u5165\u6D77\u53E3\u4FBF\u662F\u767D\u6E2F\u7684\u6CCA\u5730\u3002"],["The White Knife runs down from the North to meet the sea here.","\u767D\u5203\u6CB3\u81EA\u5317\u5883\u800C\u4E0B\uFF0C\u5728\u6B64\u6C47\u5165\u5927\u6D77\u3002"],"high",["agot","twoiaf","maps"],["White Harbor stands at the mouth of the White Knife.","\u767D\u6E2F\u4F4D\u4E8E\u767D\u5203\u6CB3\u7684\u5165\u6D77\u53E3\u3002"],["The river's exact course beside the city.","\u6CB3\u9053\u5728\u57CE\u65C1\u7684\u786E\u5207\u8D70\u5411\u3002"],["A gently curving channel and a stone bridge are invented.","\u7F13\u7F13\u5F2F\u66F2\u7684\u6CB3\u9053\u4E0E\u4E00\u5EA7\u77F3\u6865\u5747\u4E3A\u81EA\u62DF\u3002"])}};export{l as default};
